    try:
        # Check face plate thickness (y=0 to 4)
        # We probe a thin slice at y=2 to see if it's solid around the bore
        thickness_check = shape.intersect(cq.Solid.makeBox(100, 4, 100, pnt=cq.Vector(-50, 0, -50)))
        # Requirement R2: Face plate at least 4mm thick (y=0 to 4)
        # We check if the volume of material in y=[0,4] is consistent with a plate
        bbox = shape.BoundingBox()
        y_min, y_max = bbox.min.y, bbox.max.y
        thickness_ok = (y_max - 0 >= 4.0) and (y_min <= 0) # Simplified check for existence at plane

        # R3: Central bore diameter 22.5 mm through face plate on shaft axis (x=0, z=30)
        bore_diam = 22.5
        bore_pnt = cq.Vector(0, 0, 30)
        bore_dir = cq.Vector(0, 1, 0)
        # Probe core (empty)
        core = cq.Solid.makeCylinder(bore_diam/2 - 0.1, 4.1, pnt=cq.Vector(0, -0.1, 30), dir=cq.Vector(0, 1, 0))
        # Probe wall (solid)
        wall = cq.Solid.makeCylinder(bore_diam/2 + 1.0, 4.1, pnt=cq.Vector(0, -0.1, 30), dir=cq.Vector(0, 1, 0)).cut(
            cq.Solid.makeCylinder(bore_diam/2 + 0.1, 4.1, pnt=cq.Vector(0, -0.1, 30), dir=cq.Vector(0, 1, 0)))

        empty_vol = shape.intersect(core).Volume() / core.Volume()
        walled_vol = shape.intersect(wall).Volume() / wall.Volume()

        r3_ok = empty_vol < 0.05 and walled_vol > 0.9

        results["R2_R3"] = {
            "status": "pass" if (thickness_ok and r3_ok) else "fail",
            "value": [round(empty_vol, 3), round(walled_vol, 3)],
            "method": f"bore probe at (0,y,30) with D={bore_diam}, core_ratio={empty_vol}, wall_ratio={walled_vol}",
            "criteria": [
                {"condition": "Face plate thickness >= 4mm", "measured": y_max - y_min, "ok": thickness_ok},
                {"condition": "Central bore diameter 22.5mm", "measured": empty_vol, "ok": r3_ok}
            ],
            "note": f"Empty: {empty_vol}, Walled: {walled_vol}"
        }
    except Exception as e:
        results["R2_R3"] = {"status": "error", "value": None, "method": "bore probe", "criteria": [], "note": str(e)}

